<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'
import { useMutation, useQuery, useQueryClient } from '@tanstack/vue-query'
import { ArrowLeft } from '@lucide/vue'
import { NButton, NCheckbox, NDatePicker, NInput, NInputNumber, NSelect } from 'naive-ui'
import { computed, reactive, ref } from 'vue'
import { RouterLink, useRoute } from 'vue-router'
import { formatDate, serviceStatus, shopApi } from '../lib'
import type { RedemptionField } from '../types'

const route=useRoute(); const id=computed(()=>Number(route.params.id)); const client=useQueryClient(); const handler=ref<number|null>(null); const memo=ref(''); const reason=ref(''); const error=ref(''); const values=reactive<Record<number,any>>({})
const query=useQuery({queryKey:computed(()=>['shop-service',id.value]),queryFn:()=>shopApi.service(id.value)})
const handlers=useQuery({queryKey:computed(()=>['shop-service-handlers',id.value]),queryFn:()=>shopApi.serviceHandlers(id.value),enabled:computed(()=>query.data.value?.status===1)})
const handlerOptions=computed(()=>(handlers.data.value??[]).map(item=>({label:item.subject.name,value:item.entity_id})))
const customerFields=computed(()=>(query.data.value?.redemption_fields??[]).filter(f=>f.fill_stage==='customer'))
const start=useMutation({mutationFn:()=>shopApi.startService(id.value,{handler_entity_id:Number(handler.value),memo:memo.value,field_values:values}),onSuccess:async()=>{error.value='';await Promise.all([client.invalidateQueries({queryKey:['shop-service',id.value]}),client.invalidateQueries({queryKey:['shop-services']})])},onError:e=>error.value=friendlyError(e)})
const cancel=useMutation({mutationFn:()=>shopApi.cancelService(id.value,reason.value),onSuccess:async()=>{reason.value='';error.value='';await client.invalidateQueries({queryKey:['shop-service',id.value]})},onError:e=>error.value=friendlyError(e)})
const choices=(field:RedemptionField)=>(field.options??[]).map(value=>({label:value,value}))
</script>

<template><section class="service-page"><RouterLink class="back" to="/services"><ArrowLeft :size="18" />返回我的服务</RouterLink><div v-if="query.isPending.value" class="panel">正在读取…</div><article v-else-if="query.data.value"><header><div><p>SERVICE / #{{ query.data.value.id }}</p><h1 tabindex="-1">{{ query.data.value.service.name }}</h1></div><strong>{{ serviceStatus(query.data.value.status) }}</strong></header><p class="description">{{ query.data.value.service.description || '该服务暂无补充说明。' }}</p><dl><div><dt>有效期</dt><dd>{{ query.data.value.expire_time ? formatDate(query.data.value.expire_time) : '长期有效' }}</dd></div><div><dt>接单人</dt><dd>{{ query.data.value.handler?.name || query.data.value.handler?.profile?.name || '尚未选择' }}</dd></div></dl>
<form v-if="query.data.value.status===1 && !query.data.value.is_expired" @submit.prevent="start.mutate()"><h2>发起核销</h2><label>选择接单人 <NSelect v-model:value="handler" :options="handlerOptions" filterable placeholder="请选择" /></label><label v-for="field in customerFields" :key="field.id">{{ field.name }} <b v-if="field.is_required">*</b><NInput v-if="field.input_type==='textarea'||field.value_type==='text'||field.value_type==='json'" v-model:value="values[field.id]" type="textarea" /><NSelect v-else-if="['select','radio'].includes(field.input_type)||field.value_type==='select'" v-model:value="values[field.id]" :options="choices(field)" clearable /><NSelect v-else-if="field.value_type==='multi_select'||field.input_type==='checkbox'" v-model:value="values[field.id]" :options="choices(field)" multiple clearable /><NCheckbox v-else-if="field.value_type==='bool'" :checked="Boolean(values[field.id])" @update:checked="value=>values[field.id]=value?1:0">是</NCheckbox><NInputNumber v-else-if="['int','decimal'].includes(field.value_type)" v-model:value="values[field.id]" :precision="field.value_type==='int'?0:2" /><NDatePicker v-else-if="['date','datetime'].includes(field.value_type)" v-model:value="values[field.id]" :type="field.value_type==='date'?'date':'datetime'" /><NInput v-else v-model:value="values[field.id]" /></label><label>备注 <NInput v-model:value="memo" type="textarea" /></label><NButton attr-type="submit" type="primary" size="large" :disabled="!handler" :loading="start.isPending.value">提交核销</NButton></form>
<form v-else-if="query.data.value.status===2 && !(query.data.value.cancel_requests??[]).some(item=>item.status===1)" @submit.prevent="cancel.mutate()"><h2>申请取消核销</h2><label>取消原因 <NInput v-model:value="reason" type="textarea" /></label><NButton attr-type="submit" secondary type="warning" :loading="cancel.isPending.value">提交申请</NButton></form><div v-else-if="query.data.value.status===2" class="notice">取消申请正在等待处理，期间不会改派或完成核销。</div><p v-if="error" class="error" role="alert">{{ error }}</p></article></section></template>

<style scoped>.service-page{width:min(820px,calc(100% - 32px));margin:auto;padding:48px 0 96px}.back{display:inline-flex;gap:7px;align-items:center;color:#9fb0c5;margin-bottom:24px}.service-page article,.panel{padding:28px;background:#101d30;border:1px solid #263951;border-radius:16px}.service-page header{display:flex;justify-content:space-between;gap:20px}.service-page h1{margin:7px 0;font-size:clamp(2rem,6vw,3.5rem)}.service-page header p,.service-page header>strong{color:#69e4dc}.description{color:#9fb0c5}.service-page dl{display:grid;grid-template-columns:1fr 1fr;gap:12px}.service-page dl div{padding:14px;background:#0b1525;border-radius:10px}.service-page dt{color:#8093aa;font-size:.8rem}.service-page dd{margin:5px 0 0}form{display:grid;gap:16px;margin-top:28px;padding-top:24px;border-top:1px solid #263951}form label{display:grid;gap:7px}form b{color:#ff9f68}.notice{margin-top:24px;padding:16px;background:#162741;border-radius:10px;color:#b9c7d7}.error{color:#ff8d93}@media(max-width:600px){.service-page article{padding:20px}.service-page dl{grid-template-columns:1fr}}</style>
